#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
int n;
vector<vector<int>> pos;

inline bool check(int w, int l, int r, int p) {
    for(int i : pos[w]) {
        bool ok = false;
        if(p <= i) {
            int c = min(i, l) + max(0, i - (n - r));
            if(c == (i + 1) / 2) ok = true;
        }
        if(!ok && p>= i){
            int c = max(0 , l-i+1) + min (r, n-i+1);
            int m = n -i+1;
            if(c == (m+1)/2)ok = true;
        }
        if(!ok)return false;
        
    }
    return true;
}
void solve(){
    cin >> n;
    pos.assign(n+2,{});
    for(int i =1; i<= n; i++){
        int a; 
        cin >>a;
        pos[a].push_back(i);
        
    }
    vector<int>dp(n+2, 0), nd(n+2, 0);
    dp[0]= 1;
    for(int w = 1; w<= n ; w++){
        fill(nd.begin(), nd.end(), 0);
        for(int lp = 0; lp<= w-1; lp++){
            int v = dp[lp];
            if(!v )continue;
            {
                int L = lp+1;
                int R = w-L;
                if(check(w,L,R,L)){
                    nd[L] += v;
                    if(nd[L] >= MOD ) nd[L]  -= MOD;
                
                }
            }
            
            if(w<n ){
                int L = lp , R = w-L;
                if(check(w,L,R,n-R+1)){
                    nd[L] += v;
                    if(nd[L]>= MOD ) nd[L] -= MOD;
                }
            }
            
        }
        swap(dp,nd);
    }
    long long ans = 0;
    for(int L = 0; L<= n; L++){
        ans+=dp[L];
    }
    cout << (ans % MOD)<< "\n";
}

int main() {
	// your code goes here
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    
    int t;
    cin >> t;
    while(t--) {
        solve();
    }
    return 0;
}
